import{z as i,x as s,o as a,c as l,q as B,j as n,D as e,d as o,s as t,S as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"环境政策的因果证据","description":"","frontmatter":{"title":"环境政策的因果证据","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ca-env-policy-evidence.md","filePath":"econ/ca-env-policy-evidence.md","lastUpdated":1791413859000}'),c={name:"econ/ca-env-policy-evidence.md"};function d(p,E,D,h,C,_){const A=s("Mermaid");return a(),l("div",null,[E[2]||(E[2]=B('<h1 id="环境政策的因果证据" tabindex="-1">环境政策的因果证据 <a class="header-anchor" href="#环境政策的因果证据" aria-label="Permalink to &quot;环境政策的因果证据&quot;">​</a></h1><div class="epigraph"><p>环境政策天然缺一张反事实排放表：监管专挑最脏的地方下手，天真的前后比较只会高估它。</p><footer>—— 据 Chay and Greenstone, QJE 2003；Chen, Ebenstein, Greenstone and Li, PNAS 2013 整理</footer></div><p><a href="/econ/ca-health-policy-evidence">上一课</a>把健康链条「保险 → 利用 → 健康」的分段评估跑完。本课到环境政策：链条换成「规制 → 排放 → 暴露 → 健康」，且多出两层别的领域没有的困难——排放反事实无人供给，规制恰恰按污染水平选址。工具是现成的：<a href="/econ/pigouvian-carbon-price">庇古税与碳定价</a>与<a href="/econ/cap-and-trade">总量管制与许可证</a>给了政策形态，本课给它们的证据形态。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>环境规制是阈值写出来的：空气质量未达标的县被列为非达标区，承担更严的新源审查；供暖线以北享受冬季燃煤供暖。阈值同时是选择机制——被规制的正是最脏、本来就有最强改善倾向的地方。用规制前后比、或达标-未达标比，都会把<a href="/econ/pe-eventstudy-specification">事前趋势</a>与选址内生算进政策。缺口因此是双重的：既要「不规制排放会怎么走」的反事实，又要健康端的剂量反应——排放是中间变量，最终的账在死亡率与预期寿命上。</p><p><span class="marginnote">「非达标区」可以读成环保部门的不及格名单：空气质量没达标的县被点名，此后新建排放源要过更严的审查。麻烦正在这儿——名单按污染水平生成，拿名单县和名单外县直接比，比出来的既是政策效应，也混着「谁本来就脏、谁本来就正开始治理」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计围绕阈值生长。<strong>非达标 designation 的 DiD</strong>：Clean Air Act 的县名单给出处理组，非污染规制渠道的引入可以升级为三重差分——Chay–Greenstone 2003 用 1981–82 衰退造成的 TSP 外生下降对婴儿死亡率读出剂量反应。<strong>规制线的断点</strong>：淮河供暖政策把冬季燃煤供暖画在地理线上，Chen–Ebenstein–Greenstone–Li 2013 在两侧读出颗粒物浓度北高南低的跳跃与预期寿命约五年的差——一条没人选择的政策线，替研究者选好了对照。<strong>单一政策的合成</strong>：一个辖区独自开征碳税时没有两组，<a href="/econ/pe-synthetic-control-deep">合成对照的深化</a>用未开征税区的加权组合造反事实排放路径。<strong>市场工具读成本</strong>：总量管制下许可证价格本身就是边际减排成本的读数，酸雨计划的排放比 1990 年降半而成本远低于事前预测，事后的成本核算（Carlson 等 2000）把「命令 vs 交易」之争收成一笔账。</p><p><span class="marginnote">合成对照的直觉：B 地开征碳税后，世上没有「另一个 B」可对照，就用若干未征税地区加权拼出一个「合成 B」——比如 30% 的 A 地加 25% 的 C 地……凑到它在政策前的排放走势与真 B 几乎重合。政策之后两条路的分岔，就是政策的读数。</span></p>',9)),(a(),n(r,null,{default:e(()=>[t(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20POL%5B%22%E8%A7%84%E5%88%B6%EF%BC%9A%E9%98%88%E5%80%BC%E6%88%96%E6%B3%95%E7%BA%BF%22%5D%20--%3E%20EMIT%5B%22%E6%8E%92%E6%94%BE%E8%B7%AF%E5%BE%84%22%5D%0A%20%20EMIT%20--%3E%20EXPO%5B%22%E6%9A%B4%E9%9C%B2%EF%BC%9A%E6%B5%93%E5%BA%A6%E4%B8%8E%E4%BA%BA%E7%BE%A4%22%5D%0A%20%20EXPO%20--%3E%20HEALTH%5B%22%E5%81%A5%E5%BA%B7%EF%BC%9A%E6%AD%BB%E4%BA%A1%E7%8E%87%E4%B8%8E%E9%A2%84%E6%9C%9F%E5%AF%BF%E5%91%BD%22%5D%0A%20%20SEL%5B%22%E9%80%89%E5%9D%80%E5%86%85%E7%94%9F%EF%BC%9A%E6%9C%80%E8%84%8F%E5%A4%84%E8%A2%AB%E8%A7%84%E5%88%B6%22%5D%20--%3E%7C%E6%B1%A1%E6%9F%93%7C%20POL%0A%20%20DID%5B%22%E9%9D%9E%E8%BE%BE%E6%A0%87%20DiD%20%E4%B8%8E%E4%B8%89%E9%87%8D%E5%B7%AE%E5%88%86%22%5D%20--%3E%20POL%0A%20%20RDD%5B%22%E4%BE%9B%E6%9A%96%E7%BA%BF%E6%96%AD%E7%82%B9%22%5D%20--%3E%20EMIT%0A%20%20SYN%5B%22%E5%90%88%E6%88%90%E5%AF%B9%E7%85%A7%EF%BC%9A%E5%8D%95%E4%B8%80%E8%BE%96%E5%8C%BA%22%5D%20--%3E%20EMIT%0A%20%20MKT%5B%22%E8%AE%B8%E5%8F%AF%E8%AF%81%E4%BB%B7%E6%A0%BC%E8%AF%BB%E8%BE%B9%E9%99%85%E6%88%90%E6%9C%AC%22%5D%20--%3E%20POL%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[o(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<p><span class="marginnote">阈值的双刃：它给识别造断点，也给估计造偏倚。非达标区在 designation 前被选中，恰恰因为污染高且已开始治理，事后的改善里有一大块与规制无关——所以认真的研究都在阈值附近做局部比较，而不是拿名单全表比。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么环境证据对「缝隙」的依赖比劳动、健康更深：环境政策处理的是流量与存量的连续变量，随机化几乎不可能，而物理与法律各供给一批天然断点——法线、阈值、燃料税的价差。机制读数有三层。第一层是剂量反应：断点上的浓度跳跃乘以健康差，给出每单位污染的死亡率弹性，这是损害函数的锚。第二层是成本端：许可证价格与减排技术数据对上，才知道一单位减排的社会成本与收益哪个大——<a href="/econ/pigouvian-carbon-price">庇古税与碳定价</a>的税率问题从规范口号变成两个可估的量。第三层是行为反应：规制会把排放挤到未规制辖区（leakage），把监测数据挤向好看——空间替代违反<a href="/econ/potential-outcomes">潜在结果</a>的稳定单元假设，数据操纵则污染测量。不这么做会错在哪：把达标县的清洁化全部记在法规头上，或只看辖区内的排放而看不见挤出的那一块，政策的账两头都错。</p>',3)),(a(),n(r,null,{default:e(()=>[t(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E8%A7%84%E5%88%B6%E6%94%B6%E7%B4%A7%3A%20%E9%9D%9E%E8%BE%BE%E6%A0%87%E5%90%8D%E5%8D%95%E7%94%9F%E6%95%88%22%5D%20--%3E%20D1%5B%22%E5%89%82%E9%87%8F%E5%8F%8D%E5%BA%94%3A%20%E6%96%AD%E7%82%B9%E5%A4%84%E6%B5%93%E5%BA%A6%E8%B7%B3%E8%B7%83%22%5D%0A%20%20D1%20--%3E%20D2%5B%22%E6%B5%93%E5%BA%A6%E5%B7%AE%20%E4%B9%98%20%E5%81%A5%E5%BA%B7%E5%B7%AE%20%3D%20%E6%AD%BB%E4%BA%A1%E7%8E%87%E5%BC%B9%E6%80%A7%22%5D%0A%20%20D2%20--%3E%20ANCH%5B%22%E6%8D%9F%E5%AE%B3%E5%87%BD%E6%95%B0%E7%9A%84%E9%94%9A%3A%20%E6%AF%8F%E5%8D%95%E4%BD%8D%E6%B1%A1%E6%9F%93%E7%9A%84%E5%81%A5%E5%BA%B7%E4%BB%A3%E4%BB%B7%22%5D%0A%20%20R%20--%3E%20M%5B%22%E6%88%90%E6%9C%AC%E7%AB%AF%3A%20%E8%AE%B8%E5%8F%AF%E8%AF%81%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20M%20--%3E%20MC%5B%22%E8%BE%B9%E9%99%85%E5%87%8F%E6%8E%92%E6%88%90%E6%9C%AC%E8%AF%BB%E6%95%B0%2C%20%E5%AF%B9%E6%AF%94%E7%A8%8E%E7%8E%87%E5%AE%9A%E5%A4%9A%E9%AB%98%22%5D%0A%20%20R%20--%3E%20B%5B%22%E8%A1%8C%E4%B8%BA%E7%AB%AF%3A%20%E4%B8%A4%E4%B8%AA%E6%9A%97%E8%B4%A6%22%5D%0A%20%20B%20--%3E%20L%5B%22leakage%3A%20%E6%8E%92%E6%94%BE%E6%8C%A4%E8%BF%9B%E6%9C%AA%E8%A7%84%E5%88%B6%E8%BE%96%E5%8C%BA%22%5D%0A%20%20B%20--%3E%20G%5B%22%E6%95%B0%E6%8D%AE%E8%A2%AB%E6%8C%A4%E5%90%91%E5%A5%BD%E7%9C%8B%2C%20%E6%B1%A1%E6%9F%93%E6%B5%8B%E9%87%8F%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[o(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">统计生命价值（VSL）不是给命标价，是从「愿意花多少钱换一点点死亡风险下降」反推出来的交易率：比如愿付 700 元换万分之一的死亡风险降低，隐含 VSL 约为 700 万元。它是边际风险的交换比例，不是命的价格标签——初学者最常在这一步读歪，进而否定整个成本收益核算。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>环境证据的搬运门槛最高：浓度-健康弹性本地化强（人口年龄、基线污染、医疗可及都进入弹性），把一国的剂量反应直接搬进另一国要过<a href="/econ/pe-external-validity">外部有效性</a>的逐道断点；折现率与生命统计价值（VSL）的取值让成本收益核算的结论对参数敏感，这不是识别能解决的，是<a href="/econ/pe-decision-target">以决策为目标</a>的福利泛函问题。本课也不重讲<a href="/econ/externality-pigou">外部性与庇古税</a>与<a href="/econ/coase-theorem">科斯定理与交易成本</a>的理论分工——那里的增量是：科斯谈判、庇古税率与许可证市场各自的证据形态。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>环境政策的反事实双缺：排放路径与剂量反应，都靠阈值与法线供给变异。</li><li>四个设计：非达标 DiD 与三重差分、供暖线断点、单一辖区合成对照、许可证价格读成本。</li><li>阈值既造断点也造选择；leakage 与数据操纵是本领域特有的威胁。</li><li>弹性本地化与 VSL 取值让外推与核算对参数敏感，识别之外还有福利判断。</li><li>出处：Chay and Greenstone, QJE 2003；Chen, Ebenstein, Greenstone and Li, PNAS 2013；Carlson 等, AER 2000；Greenstone and Gayer 2009。</li></ul>',5))])}const m=i(c,[["render",d]]);export{f as __pageData,m as default};
